import React from "react";
import { Link } from "react-router-dom";

const Home = () => {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #fff0f6, #e6f7ff)",
        padding: "40px 20px",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      {/* HERO SECTION */}
      <div
        style={{
          maxWidth: "1100px",
          margin: "auto",
          padding: "100px 20px",
          borderRadius: "30px",
          textAlign: "center",
          backdropFilter: "blur(10px)",
          background: "rgba(255,255,255,0.6)",
          boxShadow: "0 20px 40px rgba(0,0,0,0.08)",
          animation: "fadeIn 1.2s ease",
        }}
      >
        <h1
          style={{
            fontSize: "48px",
            color: "#ff4f87",
            marginBottom: "20px",
            letterSpacing: "1px",
          }}
        >
          Nanhe Farishte – Kiran Knits
        </h1>

        <p
          style={{
            fontSize: "20px",
            color: "#555",
            marginBottom: "35px",
          }}
        >
          Har bunai mein maa ka pyaar 💖
        </p>

        <Link to="/products">
          <button
            style={{
              background: "linear-gradient(135deg, #6ec6ff, #4fb3f6)",
              border: "none",
              padding: "15px 45px",
              borderRadius: "40px",
              color: "white",
              fontSize: "17px",
              cursor: "pointer",
              transition: "0.3s ease",
              boxShadow: "0 10px 25px rgba(0,0,0,0.15)",
            }}
            onMouseOver={(e) => {
              e.target.style.transform = "scale(1.1)";
            }}
            onMouseOut={(e) => {
              e.target.style.transform = "scale(1)";
            }}
          >
            Shop Now
          </button>
        </Link>
      </div>

      {/* CATEGORY SECTION */}
      <div
        style={{
          maxWidth: "1100px",
          margin: "80px auto 0",
          textAlign: "center",
        }}
      >
        <h2
          style={{
            fontSize: "32px",
            marginBottom: "50px",
            color: "#333",
          }}
        >
          Our Categories
        </h2>

        <div
          style={{
            display: "flex",
            justifyContent: "center",
            gap: "40px",
            flexWrap: "wrap",
          }}
        >
          <CategoryCard
            emoji="🧥"
            title="Sweaters"
            link="/products?category=Sweater"
          />
          <CategoryCard
            emoji="🧦"
            title="Socks"
            link="/products?category=Socks"
          />
          <CategoryCard
            emoji="🧢"
            title="Caps"
            link="/products?category=Cap"
          />
        </div>
      </div>
    </div>
  );
};

const CategoryCard = ({ emoji, title, link }) => {
  return (
    <Link to={link} style={{ textDecoration: "none" }}>
      <div
        style={{
          background: "white",
          padding: "60px 40px",
          borderRadius: "25px",
          width: "220px",
          fontSize: "22px",
          fontWeight: "600",
          color: "#444",
          boxShadow: "0 15px 35px rgba(0,0,0,0.08)",
          transition: "0.3s ease",
          cursor: "pointer",
        }}
        onMouseOver={(e) => {
          e.currentTarget.style.transform = "translateY(-15px)";
          e.currentTarget.style.boxShadow =
            "0 25px 50px rgba(0,0,0,0.15)";
        }}
        onMouseOut={(e) => {
          e.currentTarget.style.transform = "translateY(0)";
          e.currentTarget.style.boxShadow =
            "0 15px 35px rgba(0,0,0,0.08)";
        }}
      >
        <div style={{ fontSize: "40px", marginBottom: "15px" }}>
          {emoji}
        </div>
        {title}
      </div>
    </Link>
  );
};

export default Home;
